92	 * @returns The file path and optional function name
93	 */
94	export function parseFileUrl(fileUrl: string): { filePath: string; functionName?: string } {
95	  if (!fileUrl.startsWith('file://')) {
96	    throw new Error('URL must start with file://');
97	  }
98	
99	  const urlWithoutProtocol = fileUrl.slice('file://'.length);
100	  const lastColonIndex = urlWithoutProtocol.lastIndexOf(':');
101	
102	  if (lastColonIndex > 1) {
103	    return {
104	      filePath: urlWithoutProtocol.slice(0, lastColonIndex),
105	      functionName: urlWithoutProtocol.slice(lastColonIndex + 1),
106	    };
107	  }
108	
109	  return {
110	    filePath: urlWithoutProtocol,
111	  };
112	}
