}", "newString": "export function parseFileUrl(fileUrl: string): { filePath: string; functionName?: string } {
  if (!fileUrl.startsWith('file://')) {
    throw new Error('URL must start with file://');
  }

  let urlWithoutProtocol = fileUrl.slice('file://'.length);

  // Canonical Windows file URLs take the form file:///C:/path/to/file.js, which leaves a
  // leading slash before the drive letter after the protocol is stripped. On Windows that
  // slash must be removed so the path resolves correctly; on POSIX the path is preserved
  // as-is (a leading slash there is a genuine part of the absolute path).
  if (process.platform === 'win32' && /^\/[a-zA-Z]:/.test(urlWithoutProtocol)) {
    urlWithoutProtocol = urlWithoutProtocol.slice(1);
  }

  const lastColonIndex = urlWithoutProtocol.lastIndexOf(':');

  // A colon only separates the function name when the segment before it is a JavaScript or
  // Python file. Otherwise the colon belongs to the path itself (e.g. a Windows drive
  // letter, or a colon embedded in a directory or file name) and is preserved.
  if (lastColonIndex !== -1) {
    const candidatePath = urlWithoutProtocol.slice(0, lastColonIndex);
    if (isJavascriptFile(candidatePath) || candidatePath.endsWith('.py')) {
      return {
        filePath: candidatePath,
        functionName: urlWithoutProtocol.slice(lastColonIndex + 1),
      };
    }
  }

  return {
